// Writes src/less/words.rs: the words that the big alternations of the `less`
// grammar spell out, each with its place in the alternation, sorted by word.
// The grammar follows each list with `\b`, so of the words that end where `\b`
// holds the matcher takes the one the alternation tries first, as a
// backtracking matcher does, not the longest: `\b(auto|auto-fill)\b` takes the
// `auto` of `auto-fill`.
//
// Run with `bun run oracle/less-words.ts`, which formats what it writes, and
// commit the result; the output is generated, do not edit it.
import less from "@shikijs/langs@4.6.0/less";

import { expand } from "./alternation.ts";
import { writeRust } from "./rule-grammar.ts";

type Node = { match?: string; begin?: string; patterns?: Node[]; include?: string };
const repository = (less as unknown as { repository: Record<string, Node> }[])[0]!.repository;

/** The regex of the pattern at `path` under repository entry `key`. */
function regexOf(key: string, ...path: number[]): string {
  let node = repository[key]!;
  for (const index of path) node = node.patterns![index]!;
  return (node.match ?? node.begin)!;
}

/** The alternatives at the top level of `body`. */
function alternatives(body: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let start = 0;
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c === "\\") i++;
    else if (c === "(") depth++;
    else if (c === ")") depth--;
    else if (c === "|" && depth === 0) {
      out.push(body.slice(start, i));
      start = i + 1;
    }
  }
  out.push(body.slice(start));
  return out;
}

/** The words between `prefix` and the last `suffix` of `regex`, in the order
 * the alternation tries them, each with whether it ignores case. */
function words(regex: string, prefix: string, suffix: string): [string, boolean][] {
  if (!regex.startsWith(prefix) || !regex.endsWith(suffix)) throw new Error(`${prefix}…${suffix} not around ${regex.slice(0, 60)}`);
  const body = regex.slice(prefix.length, regex.length - suffix.length);
  return alternatives(body).flatMap((alt): [string, boolean][] => {
    const folded = alt.startsWith("(?i:") && alt.endsWith(")");
    const inner = folded ? alt.slice(4, -1) : alt;
    return expand(inner).map((w) => [folded ? w.toLowerCase() : w, folded]);
  });
}

/** The table of `list`: each word once, at its first place, sorted by word. */
function table(list: [string, boolean][]): [string, number, boolean][] {
  const seen = new Map<string, [number, boolean]>();
  list.forEach(([word, folded], order) => {
    if (!/^[-.0-9:A-Za-z]+$/.test(word)) throw new Error(`${word} has a character outside [-.0-9:A-Za-z]`);
    if (word.length > 64) throw new Error(`${word} is longer than LONGEST_WORD in src/less/matchers.rs`);
    if (!seen.has(word)) seen.set(word, [order, folded]);
  });
  return [...seen].map(([word, [order, folded]]): [string, number, boolean] => [word, order, folded]).sort((a, b) => (a[0] < b[0] ? -1 : 1));
}

const lists: [string, string, [string, boolean][]][] = [
  ["EXTENDED_COLORS", "`color-values`, the extended color names", words(regexOf("color-values", 5), "\\b(", ")\\b")],
  ["COUNTER_STYLES", "`counter-functions`, the counter styles", words(regexOf("counter-functions", 0, 0, 4, 1), "\\b(", ")\\b")],
  ["VALUE_KEYWORDS", "`property-value-constants`, the keywords", words(regexOf("property-value-constants", 12), "\\b(", ")\\b")],
  ["PROPERTY_NAMES", "`rule-list-body`, the property names", words(regexOf("rule-list-body", 5, 13), "\\b(", ")\\b")],
  ["TAG_NAMES", "`selectors`, the tag names", words(regexOf("selectors", 1), "\\b(", ")\\b")],
  ["PSEUDO_CLASSES", "`pseudo-selectors`, the pseudo-classes without arguments", words(regexOf("pseudo-selectors", 5), "(:)(", ")\\b")],
  ["PSEUDO_ELEMENTS", "`pseudo-selectors`, the pseudo-elements", words(regexOf("pseudo-selectors", 8), "(::?)(", ")\\b")],
];

let out = `//! The words that the big alternations of the \`less\` grammar spell out, each
//! with its place in the alternation and whether it ignores case, sorted by
//! word. Generated by \`oracle/less-words.ts\`; do not edit.

use super::matchers::Word;

`;
for (const [name, what, list] of lists) {
  const rows = table(list)
    .map(([word, order, folded]) => `    Word { text: ${JSON.stringify(word)}, order: ${order}, folded: ${folded} },\n`)
    .join("");
  out += `/// The words of ${what}.\npub(super) const ${name}: &[Word] = &[\n${rows}];\n\n`;
}
const root = new URL("..", import.meta.url).pathname;
await writeRust(`${root}src/less/words.rs`, out.trimEnd() + "\n");
console.log(lists.map(([n, , l]) => `${n} ${table(l).length}`).join(", "));
